def main() -> None:
    if len(GROUPS) != len(RANGES):
        raise SystemExit(f"groups {len(GROUPS)} ranges {len(RANGES)}")
    expected = 1
    for start, end in RANGES:
        if start != expected:
            raise SystemExit(f"gap before {start}, expected {expected}")
        expected = end + 1
    if expected != 664:
        raise SystemExit(f"ended at {expected - 1}")
    raw = json.loads((ROOT / "cues.json").read_text(encoding="utf-8"))
    cues = []
    for (start, end), (hindi, english) in zip(RANGES, GROUPS):
        cues.append({
            "start": raw[start - 1]["start"],
            "end": raw[end - 1]["end"],
            "text": hindi,
            "english": english,
        })
    (ROOT / "cues_polished.json").write_text(
        json.dumps(cues, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    (ROOT / "hindi.srt").write_text(cues_to_srt(cues, "text"), encoding="utf-8")
    (ROOT / "english.srt").write_text(cues_to_srt(cues, "english"), encoding="utf-8")

    chapter = [
        "# Vatsalya Lila, part 1",
        "",
        "HH Radha Govind Das Goswami Maharaj.",
        "Srimad-Bhagavatam, Tenth Canto, chapter 9. Mother Yashoda churns the yogurt and begins to bind Krishna.",
        "The spoken katha's year and place are not on the recording. The file on Desire Tree is dated 3 July 2006.",
        "Hindi is given first in each section. English follows. There are no times in this chapter.",
        "",
    ]
    for hindi, english in GROUPS:
        chapter.append(hindi.strip())
        chapter.append("")
        chapter.append(english.strip())
        chapter.append("")
    (ROOT / "Chapter.md").write_text("\n".join(chapter), encoding="utf-8")

    clips = [
        "# Clips from Vatsalya Lila, part 1",
        "",
        "Times are from the start of this part. A row is one story that can stand alone.",
        "",
        "| Kind | Start | End | Topic | What he says |",
        "|---|---|---|---|---|",
    ]
    for kind, start, end, topic, what in CLIPS:
        clips.append(f"| {kind} | {start} | {end} | {topic} | {what} |")
    clips.append("")
    (ROOT / "Clips.md").write_text("\n".join(clips) + "\n", encoding="utf-8")

    meta = json.loads((ROOT / "meta.json").read_text(encoding="utf-8"))
    meta["english"] = "simple English, sentence by sentence, after the whole katha"
    meta["hindi"] = "standard Hindi spelling; Bihari ya/ja and va/ba corrected"
    meta["polished_cues"] = len(cues)
    meta["scripture"] = (
        "Srimad-Bhagavatam 10.8.46, 10.9.1-6, 10.9.8-9, 10.9.11, 10.9.13-14, "
        "and 1.8.31; Bhagavad-gita 6.47. The Padyavali verse is told as Maharaj "
        "told it; the verse number was not set."
    )
    (ROOT / "meta.json").write_text(
        json.dumps(meta, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    print("cues", len(cues), "last", round(cues[-1]["end"], 1))


if __name__ == "__main__":
    main()
